-- A record's history: the page of the underway convoy's history after a page's next token in Anvil, the same statement continuing from a time and a sequence: one range of the table's key, starting where the page before ended.
SELECT EventTime, Sequence, Operation, TO_JSON_STRING(ChangeSet) AS ChangeSet, Auth, ActorUserId, ActorUsername, PrincipalUserId, PrincipalUsername, PrincipalRole, SessionId, Process, Rpc FROM DataChangeEvents WHERE TableName = 'Missions' AND RowId = '80000000-0000-4000-8000-000000000003' AND TenantId = 'a1111111-1111-4111-8111-111111111111' AND EventTime <= TIMESTAMP '2026-11-01T00:00:00Z' AND (EventTime < TIMESTAMP '2026-11-01T00:00:00Z' OR Sequence < 1) ORDER BY EventTime DESC, Sequence DESC LIMIT 51
